#!/bin/bash
# Round 9 (vi), read-only (the director's ruling, 2026-11-27): the round-9 draft of pg_verify.py's trace check, run in
# memory on a login node against B3 run 3's graphs trace and records, in its own public-seed replay directory
# (covfix-pg/replay-20261127T050508Z). The draft pg_verify.py and pg_pins.json ride in this script (base64, their
# sha256 checked before use); the record, manifest and members come from that replay's deploy (the Y2 archive). The
# call is the replay's own (pg_replay.sh's tcheck graphs): the same trace, rc, role, tune, spline and its reduced sha,
# cwd, W root, pins, system pins, gxmlpath and xsec data, and the output; plus round 9's interpreter pins. Every file
# is read O_NOATIME|O_NOFOLLOW (O_NOFOLLOW alone where O_NOATIME is refused). Nothing is written on NERSC: the module
# is executed from memory, and the record goes to stdout only. The output stays on the laptop beside this script.
set -u
OUT="$(dirname "$0")/b3-run3-recheck.out"
[ -e "$OUT" ] && { echo "refusing: $OUT exists"; exit 5; }
H="$HOME"
exec /usr/bin/ssh -F /dev/null -o BatchMode=yes -o User=josephrb -o IdentitiesOnly=yes \
  -o IdentityFile="$H/.ssh/nersc" -o CertificateFile="$H/.ssh/nersc-cert.pub" \
  -o StrictHostKeyChecking=yes -o UserKnownHostsFile="$H/.ssh/known_hosts" \
  -o ForwardAgent=no -o ForwardX11=no -o ClearAllForwardings=yes -o PermitLocalCommand=no \
  -o ControlMaster=no -o ControlPath=none -o ConnectTimeout=30 saul.nersc.gov \
  "env -i PATH=/usr/bin:/bin LC_ALL=C /usr/bin/python3.11 -I -S -B -" > "$OUT" 2>&1 <<'REMOTE'
import base64, collections, hashlib, json, os, socket, stat, sys, types
V_SHA = "406c6da2849b30ae8ba937e6dba577842f014366b81769b53f1d570137e32682"
P_SHA = "f36b43887726ac324401a71a541a3747f2edf0e15a47ee0bfd0e21b9061e8dc7"
V_B64 = ""
P_B64 = ""
W = "/pscratch/sd/j/josephrb/covfix-pg/replay-20261127T050508Z"
R = W + "/run"
REC = W + "/deploy/docs/orchestration/state/2d-closeout/covfix-20261122/pg/record"
T = "G21_11a_00_000"
def read(p):
    if not stat.S_ISREG(os.lstat(p).st_mode):
        raise SystemExit(f"STOP: {p} is not a regular file")
    try:
        fd = os.open(p, os.O_RDONLY | os.O_NOATIME | os.O_NOFOLLOW)
    except PermissionError:
        fd = os.open(p, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        chunks = []
        while True:
            c = os.read(fd, 1 << 20)
            if not c:
                return b"".join(chunks)
            chunks.append(c)
    finally:
        os.close(fd)
v, pj = base64.b64decode(V_B64), base64.b64decode(P_B64)
if hashlib.sha256(v).hexdigest() != V_SHA or hashlib.sha256(pj).hexdigest() != P_SHA:
    raise SystemExit("STOP: an embedded file's sha differs")
print("host", socket.gethostname(), "| pg_verify", V_SHA, "| pg_pins", P_SHA, flush=True)
mod = types.ModuleType("pg_verify")
exec(compile(v, "pg_verify.py", "exec"), mod.__dict__)
pins = json.loads(pj)
spline = f"{R}/splines/{T}_CH.xml.gz"
red = json.loads(read(R + "/spline_check.json"))["reduced"]["sha256"]
gxml = read(f"{R}/gxmlpath_{T}.txt").decode().strip()
lib_pins = {x["real"]: x["sha256"] for x in pins["compat_libs"]["libs"].values()}
interp = {os.path.normpath(k): x for k, x in pins["interpreter_tools"].items()}
rec = mod.trace_check(read(f"{R}/traces/graphs_{T}.trace").decode(), 0, "graphs", T, spline, red, R,
                      json.loads(read(REC + "/PG-RECORD.json")), json.loads(read(REC + "/genie-manifest.json"))["members"],
                      json.loads(read(REC + "/G2111a-members.json"))["members"], os.path.normpath(R), {spline: red},
                      system_pins=dict(pins["system_tools"]), gxmlpath=gxml, xsec_data=gxml,
                      outputs=[f"{R}/graphs_{T}.root"], lib_pins=lib_pins, interp_pins=interp)
probs = rec.get("problems", [])
print("== pass", rec.get("pass"), "| problems", len(probs), dict(collections.Counter(p.split(":", 1)[0] for p in probs)))
for p in probs[:400]:
    print("   -", p[:400])
print("== execs")
for x in rec.get("execs", []):
    print("  ", x.get("bound_by"), x.get("real"))
print("== dotdot (allowed ones)")
for x in rec.get("dotdot", []):
    if x.get("allowed"):
        print("  ", x)
print("== counts", {k: len(x) for k, x in rec.items() if isinstance(x, list)})
print("== end")
REMOTE
